+func TestConvertToDistroAdvisoryPrefixes(t *testing.T) {
+	tests := []struct {
+		family string
+		title  string
+		want   string
+	}{
+		{constant.RedHat, "RHSA-2024:1234: Important update", "RHSA-2024:1234"},
+		{constant.CentOS, "RHBA-2024:1234: bug fix", "RHBA-2024:1234"},
+		{constant.Alma, "RHSA-2024:1234: security update", "RHSA-2024:1234"},
+		{constant.Rocky, "RHSA-2024:1234: security update", "RHSA-2024:1234"},
+		{constant.Oracle, "ELSA-2024-1234: security update", "ELSA-2024-1234"},
+		{constant.Amazon, "ALAS2-2024-1234: update", "ALAS2-2024-1234"},
+		{constant.Fedora, "FEDORA-2024-abcd update", "FEDORA-2024-abcd"},
+		{constant.RedHat, "CVE-2024-1234 issue", ""},
+		{constant.Oracle, "RHSA-2024:1234: issue", ""},
+		{constant.Amazon, "", ""},
+	}
+	for _, tt := range tests {
+		o := RedHatBase{Base: Base{family: tt.family}}
+		got := o.convertToDistroAdvisory(&ovalmodels.Definition{Title: tt.title})
+		if tt.want == "" {
+			if got != nil {
+				t.Errorf("%s %q: unexpected advisory: %#v", tt.family, tt.title, got)
+			}
+		} else if got == nil || got.AdvisoryID != tt.want {
+			t.Errorf("%s %q: want %q, got %#v", tt.family, tt.title, tt.want, got)
+		}
+	}
