+			Title:    "CVE-2024-1234 unrelated title",
+			Advisory: ovalmodels.Advisory{Cves: []ovalmodels.Cve{{CveID: "CVE-2024-1234"}}},
+		},
+		binpkgFixstat: map[string]fixStat{"pkg": {notFixedYet: true, fixState: "Fix deferred", fixedIn: "2.0"}},
+	}
+	o := RedHatBase{Base: Base{family: constant.RedHat}}
+	o.update(&r, def)
+	v := r.ScannedCves["CVE-2024-1234"]
+	if len(v.DistroAdvisories) != 0 {
+		t.Errorf("unexpected advisory: %#v", v.DistroAdvisories)
+	}
+	want := models.PackageFixStatus{Name: "pkg", NotFixedYet: true, FixState: "Fix deferred", FixedIn: "2.0"}
+	if len(v.AffectedPackages) != 1 || v.AffectedPackages[0] != want {
+		t.Errorf("want %#v, got %#v", want, v.AffectedPackages)
+	}
+}
